package com.selma.universal;
import android.opengl.*; import java.nio.*; import javax.microedition.khronos.egl.EGLConfig; import javax.microedition.khronos.opengles.GL10;
public final class UniversalRenderer implements GLSurfaceView.Renderer{
 int quality,mood,p,pos,col,mh;long start;Mesh head,body;float[] pr=new float[16],vw=new float[16],mo=new float[16],tmp=new float[16],mvp=new float[16];UniversalRenderer(int q){quality=q;}void setMood(int m){mood=m;}
 public void onSurfaceCreated(GL10 g,EGLConfig c){GLES20.glClearColor(0,0,0,0);GLES20.glEnable(GLES20.GL_DEPTH_TEST);p=prog(V,F);pos=GLES20.glGetAttribLocation(p,"a");col=GLES20.glGetUniformLocation(p,"c");mh=GLES20.glGetUniformLocation(p,"m");int sl=quality==0?10:18,st=quality==0?5:10;head=Mesh.sphere(.5f,.66f,.38f,sl,st);body=Mesh.sphere(.7f,.86f,.28f,sl,Math.max(4,st-2));start=System.currentTimeMillis();}
 public void onSurfaceChanged(GL10 g,int w,int h){GLES20.glViewport(0,0,w,h);Matrix.perspectiveM(pr,0,38,w/(float)Math.max(h,1),.1f,20);Matrix.setLookAtM(vw,0,0,.12f,4.2f,0,0,0,0,1,0);}
 public void onDrawFrame(GL10 g){GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT|GLES20.GL_DEPTH_BUFFER_BIT);GLES20.glUseProgram(p);float t=(System.currentTimeMillis()-start)/1000f,b=(float)Math.sin(t*2)*.025f,turn=(float)Math.sin(t*.7f)*7f,pulse=mood==1?(float)Math.sin(t*8)*.05f:0;draw(body,0,-.95f+b,1,1+b,1,.07f,.2f,.3f,.92f,turn);draw(head,0,.12f+b,1+pulse,1+pulse,1+pulse,.69f,.47f,.34f,.98f,turn);}
 void draw(Mesh x,float px,float py,float sx,float sy,float sz,float r,float g,float b,float a,float ry){Matrix.setIdentityM(mo,0);Matrix.translateM(mo,0,px,py,0);Matrix.rotateM(mo,0,ry,0,1,0);Matrix.scaleM(mo,0,sx,sy,sz);Matrix.multiplyMM(tmp,0,vw,0,mo,0);Matrix.multiplyMM(mvp,0,pr,0,tmp,0);GLES20.glUniform4f(col,r,g,b,a);GLES20.glUniformMatrix4fv(mh,1,false,mvp,0);GLES20.glEnableVertexAttribArray(pos);GLES20.glVertexAttribPointer(pos,3,GLES20.GL_FLOAT,false,0,x.buf);GLES20.glDrawArrays(GLES20.GL_TRIANGLES,0,x.n);GLES20.glDisableVertexAttribArray(pos);}
 static int prog(String v,String f){int vs=sh(35633,v),fs=sh(35632,f),p=GLES20.glCreateProgram();GLES20.glAttachShader(p,vs);GLES20.glAttachShader(p,fs);GLES20.glLinkProgram(p);return p;}static int sh(int t,String s){int h=GLES20.glCreateShader(t);GLES20.glShaderSource(h,s);GLES20.glCompileShader(h);return h;}static final String V="uniform mat4 m;attribute vec4 a;void main(){gl_Position=m*a;}";static final String F="precision mediump float;uniform vec4 c;void main(){gl_FragColor=c;}";
 static final class Mesh{FloatBuffer buf;int n;Mesh(float[] d){n=d.length/3;buf=ByteBuffer.allocateDirect(d.length*4).order(ByteOrder.nativeOrder()).asFloatBuffer();buf.put(d).position(0);}static Mesh sphere(float rx,float ry,float rz,int sl,int st){java.util.ArrayList<Float>o=new java.util.ArrayList<>();for(int i=0;i<st;i++){double a0=Math.PI*(-.5+(double)i/st),a1=Math.PI*(-.5+(double)(i+1)/st);for(int j=0;j<sl;j++){double b0=2*Math.PI*j/sl,b1=2*Math.PI*(j+1)/sl;float[]p0=p(rx,ry,rz,a0,b0),p1=p(rx,ry,rz,a1,b0),p2=p(rx,ry,rz,a1,b1),p3=p(rx,ry,rz,a0,b1);add(o,p0);add(o,p1);add(o,p2);add(o,p0);add(o,p2);add(o,p3);}}float[]a=new float[o.size()];for(int i=0;i<o.size();i++)a[i]=o.get(i);return new Mesh(a);}static float[]p(float x,float y,float z,double a,double b){return new float[]{(float)(x*Math.cos(a)*Math.cos(b)),(float)(y*Math.sin(a)),(float)(z*Math.cos(a)*Math.sin(b))};}static void add(java.util.ArrayList<Float>o,float[]p){o.add(p[0]);o.add(p[1]);o.add(p[2]);}}
}
